00038 #ifndef __MV__
00039 #define __MV__
00040 
00041 #include "CommonDef.h"
00042 
00043 namespace vtm {
00044 
00047 
00048 // ====================================================================================================================
00049 // Class definition
00050 // ====================================================================================================================
00051 
00052 enum MvPrecision
00053 {
00054   MV_PRECISION_4PEL     = 0,      // 4-pel
00055   MV_PRECISION_INT      = 2,      // 1-pel, shift 2 bits from 4-pel
00056   MV_PRECISION_HALF     = 3,      // 1/2-pel
00057   MV_PRECISION_QUARTER  = 4,      // 1/4-pel (the precision of regular MV difference signaling), shift 4 bits from 4-pel
00058   MV_PRECISION_SIXTEENTH = 6,     // 1/16-pel (the precision of internal MV), shift 6 bits from 4-pel
00059   MV_PRECISION_INTERNAL = 2 + MV_FRACTIONAL_BITS_INTERNAL,
00060 };
00061 
00063 class Mv
00064 {
00065 private:
00066   static const MvPrecision m_amvrPrecision[4];
00067   static const MvPrecision m_amvrPrecAffine[3];
00068   static const MvPrecision m_amvrPrecIbc[3];
00069 
00070   static const int mvClipPeriod = (1 << MV_BITS);
00071   static const int halfMvClipPeriod = (1 << (MV_BITS - 1));
00072 
00073 public:
00074   int   hor;     
00075   int   ver;     
00076 
00077   // ------------------------------------------------------------------------------------------------------------------
00078   // constructors
00079   // ------------------------------------------------------------------------------------------------------------------
00080 
00081   Mv(                    ) : hor( 0    ), ver( 0    ) {}
00082   Mv( int iHor, int iVer ) : hor( iHor ), ver( iVer ) {}
00083 
00084   // ------------------------------------------------------------------------------------------------------------------
00085   // set
00086   // ------------------------------------------------------------------------------------------------------------------
00087 
00088   void  set       ( int iHor, int iVer)     { hor = iHor;  ver = iVer; }
00089   void  setHor    ( int i )                 { hor = i;                 }
00090   void  setVer    ( int i )                 { ver = i;                 }
00091   void  setZero   ()                        { hor = ver = 0;           }
00092 
00093   // ------------------------------------------------------------------------------------------------------------------
00094   // get
00095   // ------------------------------------------------------------------------------------------------------------------
00096 
00097   int   getHor    () const { return hor;          }
00098   int   getVer    () const { return ver;          }
00099   int   getAbsHor () const { return abs( hor );   }
00100   int   getAbsVer () const { return abs( ver );   }
00101 
00102   // ------------------------------------------------------------------------------------------------------------------
00103   // operations
00104   // ------------------------------------------------------------------------------------------------------------------
00105 
00106   const Mv& operator += (const Mv& _rcMv)
00107   {
00108     {
00109       Mv rcMv = _rcMv;
00110 
00111       hor += rcMv.hor;
00112       ver += rcMv.ver;
00113     }
00114     return  *this;
00115   }
00116 
00117   const Mv& operator-= (const Mv& _rcMv)
00118   {
00119     {
00120       Mv rcMv = _rcMv;
00121 
00122       hor -= rcMv.hor;
00123       ver -= rcMv.ver;
00124     }
00125     return  *this;
00126   }
00127 
00128 
00130   void divideByPowerOf2 (const int i)
00131   {
00132     if (i != 0)
00133     {
00134       const int offset = (1 << (i - 1));
00135       hor = (hor + offset - (hor >= 0)) >> i;
00136       ver = (ver + offset - (ver >= 0)) >> i;
00137     }
00138   }
00139 
00140   const Mv& operator<<= (const int i)
00141   {
00142     hor <<= i;
00143     ver <<= i;
00144     return  *this;
00145   }
00146 
00147   const Mv& operator>>= ( const int i )
00148   {
00149     if (i != 0)
00150     {
00151       const int offset = (1 << (i - 1));
00152       hor = (hor + offset - (hor >= 0)) >> i;
00153       ver = (ver + offset - (ver >= 0)) >> i;
00154     }
00155     return  *this;
00156   }
00157 
00158   const Mv operator - ( const Mv& rcMv ) const
00159   {
00160     return Mv( hor - rcMv.hor, ver - rcMv.ver );
00161   }
00162 
00163   const Mv operator + ( const Mv& rcMv ) const
00164   {
00165     return Mv( hor + rcMv.hor, ver + rcMv.ver );
00166   }
00167 
00168   bool operator== ( const Mv& rcMv ) const
00169   {
00170     return ( hor == rcMv.hor && ver == rcMv.ver );
00171   }
00172 
00173   bool operator!= ( const Mv& rcMv ) const
00174   {
00175     return !( *this == rcMv );
00176   }
00177 
00178   const Mv scaleMv( int iScale ) const
00179   {
00180     const int mvx = Clip3(MV_MIN, MV_MAX, (iScale * getHor() + 128 - (iScale * getHor() >= 0)) >> 8);
00181     const int mvy = Clip3(MV_MIN, MV_MAX, (iScale * getVer() + 128 - (iScale * getVer() >= 0)) >> 8);
00182     return Mv( mvx, mvy );
00183   }
00184 
00185   void changePrecision(const MvPrecision& src, const MvPrecision& dst)
00186   {
00187     const int shift = (int)dst - (int)src;
00188     if (shift >= 0)
00189     {
00190       *this <<= shift;
00191     }
00192     else
00193     {
00194       const int rightShift = -shift;
00195       const int nOffset = 1 << (rightShift - 1);
00196       hor = hor >= 0 ? (hor + nOffset - 1) >> rightShift : (hor + nOffset) >> rightShift;
00197       ver = ver >= 0 ? (ver + nOffset - 1) >> rightShift : (ver + nOffset) >> rightShift;
00198     }
00199   }
00200 
00201   void roundToPrecision(const MvPrecision& src, const MvPrecision& dst)
00202   {
00203     changePrecision(src, dst);
00204     changePrecision(dst, src);
00205   }
00206 
00207   // translational MV
00208   void changeTransPrecInternal2Amvr(const int amvr)
00209   {
00210     changePrecision(MV_PRECISION_INTERNAL, m_amvrPrecision[amvr]);
00211   }
00212 
00213   void changeTransPrecAmvr2Internal(const int amvr)
00214   {
00215     changePrecision(m_amvrPrecision[amvr], MV_PRECISION_INTERNAL);
00216   }
00217 
00218   void roundTransPrecInternal2Amvr(const int amvr)
00219   {
00220     roundToPrecision(MV_PRECISION_INTERNAL, m_amvrPrecision[amvr]);
00221   }
00222 
00223   // affine MV
00224   void changeAffinePrecInternal2Amvr(const int amvr)
00225   {
00226     changePrecision(MV_PRECISION_INTERNAL, m_amvrPrecAffine[amvr]);
00227   }
00228 
00229   void changeAffinePrecAmvr2Internal(const int amvr)
00230   {
00231     changePrecision(m_amvrPrecAffine[amvr], MV_PRECISION_INTERNAL);
00232   }
00233 
00234   void roundAffinePrecInternal2Amvr(const int amvr)
00235   {
00236     roundToPrecision(MV_PRECISION_INTERNAL, m_amvrPrecAffine[amvr]);
00237   }
00238 
00239   // IBC block vector
00240   void changeIbcPrecInternal2Amvr(const int amvr)
00241   {
00242     changePrecision(MV_PRECISION_INTERNAL, m_amvrPrecIbc[amvr]);
00243   }
00244 
00245   void changeIbcPrecAmvr2Internal(const int amvr)
00246   {
00247     changePrecision(m_amvrPrecIbc[amvr], MV_PRECISION_INTERNAL);
00248   }
00249 
00250   void roundIbcPrecInternal2Amvr(const int amvr)
00251   {
00252     roundToPrecision(MV_PRECISION_INTERNAL, m_amvrPrecIbc[amvr]);
00253   }
00254 
00255 
00256   Mv getSymmvdMv(const Mv& curMvPred, const Mv& tarMvPred)
00257   {
00258     return Mv(tarMvPred.hor - hor + curMvPred.hor, tarMvPred.ver - ver + curMvPred.ver);
00259   }
00260 
00261   void clipToStorageBitDepth()
00262   {
00263     hor = Clip3( -(1 << 17), (1 << 17) - 1, hor );
00264     ver = Clip3( -(1 << 17), (1 << 17) - 1, ver );
00265   }
00266   void mvCliptoStorageBitDepth()  // periodic clipping
00267   {
00268     hor = (hor + mvClipPeriod) & (mvClipPeriod - 1);
00269     hor = (hor >= halfMvClipPeriod) ? (hor - mvClipPeriod) : hor;
00270     ver = (ver + mvClipPeriod) & (mvClipPeriod - 1);
00271     ver = (ver >= halfMvClipPeriod) ? (ver - mvClipPeriod) : ver;
00272   }
00273 };// END CLASS DEFINITION MV
00274 
00275 } // namespace vtm
00276 
00277 namespace std {
00278   template <>
00279   struct hash<vtm::Mv> : public unary_function<vtm::Mv, uint64_t>
00280   {
00281     uint64_t operator()(const vtm::Mv& value) const
00282     {
00283       return (((uint64_t)value.hor << 32) + value.ver);
00284     }
00285   };
00286 };
00287 
