00291 void clipMvInPic ( Mv& rcMv, const struct Position& pos, const struct Size& size, const class SPS& sps, const class PPS& pps );
00292 void clipMvInSubpic ( Mv& rcMv, const struct Position& pos, const struct Size& size, const class SPS& sps, const class PPS& pps );
00293 
00294 bool wrapClipMv( Mv& rcMv, const Position& pos,
00295                  const struct Size& size,
00296                  const SPS *sps
00297                , const PPS* pps
00298 );
00299 
00300 void roundAffineMv( int& mvx, int& mvy, int nShift );
00301 
00303 
00304 } // namespace vtm
00305 
00306 #endif // __MV__
